def inline(s):
 s=html.escape(s)
 s=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',s)
 s=re.sub(r'(https://[^\s<;]+)',lambda m:'<a href="'+m[1].rstrip('.')+'">'+m[1].rstrip('.')+'</a>',s)
 return s

def md(source):
 source=re.sub(r'^---\n.*?\n---\n','',source,flags=re.S)
 source=re.sub(r'^# .*\n','',source,count=1)
 source=re.sub(r'^(Revisão editorial e técnica antes|Nota editorial:).*$', '',source,flags=re.M)
 source=source.replace('https://docs.alfresco.com/content-services/community/','https://alfresco.github.io/acs-deployment/')
 blocks=[]; lines=source.splitlines();i=0
 while i<len(lines):
  line=lines[i].strip();i+=1
  if not line:continue
  if line.startswith('## '):blocks.append('<h2>'+inline(line[3:])+'</h2>');continue
  if line.startswith('|'):
   rows=[line]
   while i<len(lines) and lines[i].strip().startswith('|'):rows.append(lines[i].strip());i+=1
   cells=lambda row:[inline(c.strip()) for c in row.strip('|').split('|')]
   blocks.append('<div class="table"><table><thead><tr>'+''.join('<th scope="col">'+c+'</th>' for c in cells(rows[0]))+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in cells(r))+'</tr>' for r in rows[2:])+'</tbody></table></div>');continue
  if re.match(r'^(\d+\. |[-*] )',line):
   ordered=line[0].isdigit();items=[re.sub(r'^(\d+\. |[-*] )','',line)]
   while i<len(lines) and re.match(r'^(\d+\. |[-*] )',lines[i].strip()):items.append(re.sub(r'^(\d+\. |[-*] )','',lines[i].strip()));i+=1
   tag='ol' if ordered else 'ul';blocks.append('<'+tag+'>'+''.join('<li>'+inline(x)+'</li>' for x in items)+'</'+tag+'>');continue
  para=[line]
  while i<len(lines) and lines[i].strip() and not re.match(r'^(## |\||\d+\. |[-*] )',lines[i].strip()):para.append(lines[i].strip());i+=1
  blocks.append('<p>'+inline(' '.join(para))+'</p>')
 return '\n'.join(blocks)

CALC='''<section class="box" aria-labelledby="calc-title"><h2 id="calc-title">Simulador de custo total</h2><p>Preencha os custos de cada proposta. Valores iniciais zerados: este simulador não é tabela de preços da Arquindex. Use a mesma moeda, escopo e período nos dois cenários. Não há envio nem armazenamento dos valores.</p><label>Horizonte em meses <input id="months" type="number" min="1" max="120" value="36"></label><div class="grid"><fieldset><legend>Alfresco em nuvem dedicada</legend><label>Implantação e migração (R$)<input id="a0" type="number" min="0" value="0"></label><label>Custo mensal completo (R$)<input id="am" type="number" min="0" value="0"></label><label>Custos pontuais adicionais (R$)<input id="ax" type="number" min="0" value="0"></label></fieldset><fieldset><legend>SaaS</legend><label>Implantação e migração (R$)<input id="b0" type="number" min="0" value="0"></label><label>Custo mensal completo (R$)<input id="bm" type="number" min="0" value="0"></label><label>Custos pontuais adicionais (R$)<input id="bx" type="number" min="0" value="0"></label></fieldset></div><output id="result" aria-live="polite">Preencha os dois cenários para comparar.</output><p>O mensal deve incluir infraestrutura, licenças, OCR/IA, suporte, backup e segurança quando cobrados. Os adicionais podem incluir integração, treinamento e saída contratual. Cálculo nominal: sem juros, inflação ou reajustes; inclua esses efeitos no orçamento para uma análise financeira completa.</p></section><script>const ids=['months','a0','am','ax','b0','bm','bx'];function calc(){const v=id=>Math.max(0,Number(document.getElementById(id).value)||0);const m=Math.max(1,Math.min(120,v('months')));const a=v('a0')+v('am')*m+v('ax'),b=v('b0')+v('bm')*m+v('bx');const f=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});document.getElementById('result').textContent=(a+b)?`Em ${m} meses: dedicada ${f(a)} · SaaS ${f(b)} · diferença nominal ${f(Math.abs(a-b))}. Compare também requisitos e riscos.`:'Preencha os dois cenários para comparar.'}ids.forEach(id=>document.getElementById(id).addEventListener('input',calc));</script>'''

